mapper.select:
SELECT
    ROUND(COALESCE(SUM(actualAmount), 0), 2) AS totalSales,
    ROUND(COALESCE(SUM(amount - actualAmount), 0), 2) AS totalCost,
    ROUND(COALESCE(SUM(actualAmount - (amount - actualAmount)), 0), 2) AS totalProfit
FROM bq_drug_sales
WHERE deleted = 0
AND created >= #{startTime}
AND created <= #{endTime}
AND operatorPerson = #{doctor}
